// FINMENTOR Command Center — Settings sheet rows to a config object.
//
// Deployed as the n8n Code node "Settings to Object".
//
// Divergence from the shared version used by other workflows: the hardcoded owner chat id
// fallback has been removed. A literal id baked into code is an authorisation bypass — it
// keeps granting access even if the owner clears or changes the allowlist in Settings.
// The Settings sheet is now the only policy source, and an unset allowlist denies everyone.

const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def) {
  if (v === undefined || v === '') return def;
  return String(v).toLowerCase() === 'true' || v === '1';
}
function num(v, def) {
  const n = Number(v);
  return Number.isFinite(n) ? n : def;
}
const cfg = {
  owner_chat_id: settings.owner_chat_id || '',
  manager_chat_id: settings.manager_chat_id || '',
  // No literal fallback. Empty here means deny-all downstream.
  allowed_chat_ids: (settings.allowed_chat_ids || settings.owner_chat_id || ''),
  sla_hot_hours: num(settings.sla_hot_hours, 4),
  sla_warm_hours: num(settings.sla_warm_hours, 24),
  sla_repeat_hours: num(settings.sla_repeat_hours, 6),
  default_responsible: settings.default_responsible || 'Геннадий',
  ai_model: settings.ai_model || 'gpt-4.1-mini',
  ai_enabled_for_hot: bool(settings.ai_enabled_for_hot, true),
  ai_enabled_for_warm: bool(settings.ai_enabled_for_warm, true),
  ai_enabled_for_cold: bool(settings.ai_enabled_for_cold, false),
  auto_reply_enabled: bool(settings.auto_reply_enabled, false),
  auto_reply_default_lang: (settings.auto_reply_default_lang || 'ru').toLowerCase(),
  follow_up_enabled: bool(settings.follow_up_enabled, false),
  followup_hot_hours: num(settings.followup_hot_hours, 24),
  followup_warm_hours: num(settings.followup_warm_hours, 72),
  timezone: settings.timezone || 'Europe/Chisinau',
  currency: settings.currency || 'EUR'
};
return [{ json: { settings: cfg } }];

// FINMENTOR Command Center v3 — authorisation and command parsing.
//
// Deployed as the n8n Code node "Parse Lead Command v2".
//
// Identity comes ONLY from "Verify Telegram Identity", which derives it from the
// authenticated Telegram Trigger update. No value here originates from a caller-supplied
// HTTP body, and there is no hardcoded owner fallback: the Settings sheet is the single
// authorisation policy source. An absent or empty allowlist denies everyone.
//
// Unauthorised updates return [] — a silent drop. Nothing downstream executes, so there
// are zero Pipeline reads, zero CRM writes and no CRM data in any Telegram reply.

const v = $('Verify Telegram Identity').first().json;
if (!v || v.verified !== true) return [];

const cfg = $('Settings to Object').first().json.settings || {};

// Policy source of truth. Deny-all when unset — never allow-all.
const allowed = String(cfg.allowed_chat_ids ?? '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);
if (allowed.length === 0) return [];

const fromId = String(v.verified_from_id);
const chatId = String(v.verified_chat_id);

// Re-assert the private-chat invariant at the authorisation boundary. Defence in depth:
// authorisation and reply destination must be the same identity, checked again here so a
// future change upstream cannot silently reintroduce the from/chat split.
if (!chatId || chatId !== fromId) return [];

// Exact match only. No prefix, substring or numeric coercion.
if (!allowed.includes(fromId)) return [];

const text = String(v.text ?? '').trim();
if (!text) return [];

const isCb = v.is_callback === true;
const cbId = String(v.callback_query_id ?? '');

function base(extra) {
  return Object.assign({
    mode: 'noop', query_type: '', command: '', lead_id: '', args: [],
    snooze_hours: 24, stage_value: '', note_text: '', deal_value: '', close_reason: '', meeting_date: '',
    chat_id: chatId, from_id: fromId, callback_query_id: cbId, is_callback: isCb,
    // STAGE 2 — carried through untouched from the authenticated identity gate. Nothing here is
    // read from the message body, and none of it participates in authorisation.
    message_id: v.message_id ?? null,
    message_chat_id: String(v.message_chat_id ?? ''),
    message_text: String(v.message_text ?? ''),
    message_entities: Array.isArray(v.message_entities) ? v.message_entities : [],
    origin_had_done: v.origin_had_done === true,
    allowed: true, reply_text: ''
  }, extra || {});
}

// callback_data: "cmd|lead|arg" ; text: "cmd lead arg..."
const parts = isCb
  ? text.split('|').map(s => s.trim())
  : text.replace(/^\//, '/').split(/\s+/);

const cmd = (parts[0] || '').toLowerCase().replace(/^\//, '');
const rest = parts.slice(1);

const HELP =
`FINMENTOR Command Center

Запросы:
/today — новые лиды сегодня
/overdue — просроченные follow-up
/hot — горячие лиды
/pipeline — сводка воронки
/lead <ID> — карточка лида

Действия (<ID> = FIN-/fm-/FM-...):
done <ID> — закрыть SLA
snooze <ID> <часы> — отложить
stage <ID> <стадия> — сменить стадию
meeting <ID> <дата> — назначить встречу
docs <ID> — запросить документы
proposal <ID> — отправлено предложение
nurture <ID> — в подогрев
won <ID> <сумма> — сделка выиграна
lost <ID> <причина> — сделка проиграна
note <ID> <текст> — заметка`;

const queryCmds = { today: 'today', overdue: 'overdue', hot: 'hot', pipeline: 'pipeline' };
const updateCmds = ['done', 'snooze', 'stage', 'meeting', 'docs', 'proposal', 'nurture', 'won', 'lost', 'note'];

if (cmd === 'help' || cmd === 'start') {
  return [base({ mode: 'help', reply_text: HELP })];
}

if (queryCmds[cmd]) {
  return [base({ mode: 'query', query_type: queryCmds[cmd] })];
}

if (cmd === 'lead') {
  const id = rest[0] || '';
  if (!id) return [base({ mode: 'help', reply_text: 'Укажи Lead ID: /lead FIN-...' })];
  return [base({ mode: 'query', query_type: 'lead', lead_id: id })];
}

if (updateCmds.includes(cmd)) {
  const id = rest[0] || '';
  if (!id) return [base({ mode: 'help', reply_text: `Укажи Lead ID: ${cmd} FIN-...` })];
  const o = base({ mode: 'update', command: cmd, lead_id: id, args: rest.slice(1) });
  if (cmd === 'snooze') o.snooze_hours = Number(rest[1]) > 0 ? Number(rest[1]) : 24;
  if (cmd === 'stage') o.stage_value = rest.slice(1).join(' ') || 'Discovery Scheduled';
  if (cmd === 'meeting') o.meeting_date = rest.slice(1).join(' ');
  if (cmd === 'won') o.deal_value = rest[1] || '';
  if (cmd === 'lost') o.close_reason = rest.slice(1).join(' ');
  if (cmd === 'note') o.note_text = rest.slice(1).join(' ');
  return [o];
}

// Unknown command: help text only. No CRM read, no CRM write.
return [base({ mode: 'help', reply_text: 'Неизвестная команда. Напиши /help для списка.' })];

// Формирует ответ на /today /overdue /hot /pipeline /lead
const cmd = $('Parse Lead Command v2').first().json;
const cfg = $('Settings to Object').first().json.settings || {};
const rows = $input.all().map(i => i.json);
const TZ = cfg.timezone || 'Europe/Chisinau';
const now = new Date();

function val(r,...k){ for(const x of k){ if(r[x]!==undefined&&r[x]!==null&&String(r[x]).trim()!=='') return String(r[x]).trim(); } return ''; }
function dkey(v){ const d=new Date(v); return Number.isNaN(d.getTime())?'':d.toLocaleDateString('en-CA',{timeZone:TZ}); }
function today(){ return now.toLocaleDateString('en-CA',{timeZone:TZ}); }
function isClosed(s){ s=s.toLowerCase(); return ['won','lost','closed','nurture','закрыт'].some(x=>s.includes(x)); }
function line(r,i){ return `${i}. ${val(r,'company')||'—'} / ${val(r,'name')||'—'} [${val(r,'priority')||'—'}/${val(r,'financial_zone')||'—'}]\n   ${val(r,'next_action')||'—'} | ${val(r,'lead_id')}`; }

function slaStatus(r) { return val(r,'sla_status').toLowerCase(); }
function isSnoozedFuture(r) {
  const s = slaStatus(r);
  const until = val(r,'sla_snooze_until');
  if (s !== 'snoozed' || !until) return false;
  const d = new Date(until);
  return !Number.isNaN(d.getTime()) && d > now;
}
function isInactiveForOverdue(r) {
  const stage = val(r,'deal_stage').toLowerCase();
  const sla = slaStatus(r);
  return (
    ['won','lost','closed','nurture','incomplete','закрыт'].some(x => stage.includes(x)) ||
    sla === 'done' ||
    sla === 'nurture' ||
    isSnoozedFuture(r)
  );
}

let msg = '';
const t = cmd.query_type;

if (t === 'lead') {
  const r = rows.find(x => val(x,'lead_id').toLowerCase() === String(cmd.lead_id).toLowerCase());
  if (!r) msg = `Lead ID не найден: ${cmd.lead_id}`;
  else msg =
`Карточка лида ${val(r,'lead_id')}
Компания: ${val(r,'company')||'—'}
Контакт: ${val(r,'name')||'—'} | ${[val(r,'phone'),val(r,'telegram'),val(r,'email')].filter(Boolean).join(' · ')||'—'}
Приоритет/Зона: ${val(r,'priority')||'—'} / ${val(r,'financial_zone')||'—'}
Стадия: ${val(r,'deal_stage')||'New'}
Боль: ${val(r,'main_pain')||'—'}
Next action: ${val(r,'next_action')||'—'}
Follow-up: ${val(r,'next_follow_up_at')||'—'}
SLA: ${val(r,'sla_status')||'—'}
AI-план: ${val(r,'ai_plan_ready')||'—'}`;
} else if (t === 'today') {
  const list = rows.filter(r => dkey(val(r,'created_at')) === today());
  msg = `Новые лиды сегодня: ${list.length}\n\n` + (list.length ? list.slice(0,15).map((r,i)=>line(r,i+1)).join('\n') : '—');
} else if (t === 'overdue') {
  const list = rows.filter(r => {
    const f = val(r,'next_follow_up_at');
    if (!f || isInactiveForOverdue(r)) return false;
    const d = new Date(f);
    return !Number.isNaN(d.getTime()) && d < now;
  })
    .sort((a,b)=>new Date(val(a,'next_follow_up_at'))-new Date(val(b,'next_follow_up_at')));
  msg = `Просроченные follow-up: ${list.length}\n\n` + (list.length ? list.slice(0,15).map((r,i)=>line(r,i+1)).join('\n') : '—');
} else if (t === 'hot') {
  const list = rows.filter(r => val(r,'priority').toUpperCase()==='HOT' && !isClosed(val(r,'deal_stage')));
  msg = `HOT лиды: ${list.length}\n\n` + (list.length ? list.slice(0,15).map((r,i)=>line(r,i+1)).join('\n') : '—');
} else if (t === 'pipeline') {
  const active = rows.filter(r => !isClosed(val(r,'deal_stage')));
  const byP = p => active.filter(r => val(r,'priority').toUpperCase()===p).length;
  const stages = {};
  for (const r of active){ const s=val(r,'deal_stage')||'New'; stages[s]=(stages[s]||0)+1; }
  const red = active.filter(r => ['RED','ORANGE'].includes(val(r,'financial_zone').toUpperCase())).length;
  msg = `Воронка (активных: ${active.length})
HOT ${byP('HOT')} · WARM ${byP('WARM')} · COLD ${byP('COLD')} · INCOMPLETE ${byP('INCOMPLETE')}
RED/ORANGE: ${red}

По стадиям:
${Object.entries(stages).map(([k,v])=>`• ${k}: ${v}`).join('\n')||'—'}`;
} else {
  msg = 'Нет данных.';
}

if (msg.length > 3800) msg = msg.slice(0,3800) + '\n...\nПолный список в Google Sheets.';
return [{ json: { reply_text: msg, chat_id: cmd.chat_id, callback_query_id: cmd.callback_query_id } }];

// ===================== FINMENTOR LEAD ALERT ACTIONS — one decision module =====================
//
// Spliced into the alert renderers (which actions, which keyboard shape) and into the Command
// Center (which columns an action owns, what the owner is told). One module, because the button a
// tap came from and the write that tap performs are two halves of one contract, and they drifted
// once already: the deployed keyboard offered «✅ Done» while the mutation only closed an SLA.
//
// It depends on the presenter for escaping and date rendering — `LA` must be in scope. It never
// re-implements `esc`, `card`, `join` or `dateTime`: a second date formatter is a second clock.
//
// ── WHAT THE AUDIT MEASURED, AND WHAT THIS CHANGES ─────────────────────────────────────────────
//
// Nothing here invents a business action. Every mutation below is the one already deployed in
// `Find & Build Update`, narrowed to the columns it actually owns. The labels change, the layout
// changes, the confirmations become truthful, and the writes stop carrying fifteen pre-read
// columns. The callback_data strings are byte-identical to what is already in production, so every
// historical Telegram message keeps working.
const LAA = (function () {
  'use strict';

  // ── D3 — the owner-facing labels, exactly as approved ────────────────────────────────────────
  //
  // Icons are permitted in buttons only; the alert body stays emoji-free. «Обработано», not
  // «Выполнено» (D7): the measured action closes SLA handling, it does not close the deal.
  var LABEL = {
    done: '✅ Обработано',
    snooze: '⏰ На 24 часа',
    discovery: '📞 Discovery',
    docs: '📄 Документы',
    nurture: '🗂 В Nurture'
  };

  // ── callback_data is PRESERVED VERBATIM ──────────────────────────────────────────────────────
  //
  // The handler contract is already correct, so renaming a callback for presentation would break
  // every alert already sitting in the owner's Telegram history for nothing. `won|` is deliberately
  // absent from the emitters and deliberately still routed by the Command Center (D1).
  function callbackData(action, leadId) {
    var id = String(leadId == null ? '' : leadId);
    if (action === 'done') { return 'done|' + id; }
    if (action === 'snooze') { return 'snooze|' + id + '|24'; }
    if (action === 'discovery') { return 'stage|' + id + '|Discovery Scheduled'; }
    if (action === 'docs') { return 'docs|' + id; }
    if (action === 'nurture') { return 'nurture|' + id; }
    return '';
  }

  // ── D2 — the owner-approved action sets, in the owner's order ────────────────────────────────
  //
  // NEW LEAD deliberately omits «Обработано»: a lead that arrived seconds ago has not been
  // handled, and offering the SLA-closing action as a first response invites closing an SLA that
  // never opened. It also omits Won (D1).
  var SET = {
    new_lead: ['discovery', 'docs', 'snooze', 'nurture'],
    priority: ['done', 'snooze', 'discovery', 'docs', 'nurture'],
    followup: ['done', 'snooze', 'discovery', 'docs', 'nurture']
  };

  // Terminal states carry NO keyboard. Only existing Pipeline values are read — no new taxonomy,
  // no new column.
  var TERMINAL_SLA = ['done', 'nurture'];
  var TERMINAL_STAGE = ['nurture', 'won'];

  // The state an action would set. An action whose result is already the current state is hidden
  // from the keyboard and refused harmlessly by the handler (D11) — the two must agree, which is
  // why they read the same table.
  var CURRENT_STATE_OF = {
    discovery: { field: 'deal_stage', value: 'discovery scheduled' },
    docs: { field: 'deal_stage', value: 'documents requested' }
  };

  function norm(v) { return String(v === undefined || v === null ? '' : v).trim().toLowerCase(); }

  function isTerminal(state) {
    var s = state || {};
    return TERMINAL_SLA.indexOf(norm(s.sla_status)) !== -1
      || TERMINAL_STAGE.indexOf(norm(s.deal_stage)) !== -1;
  }

  // The actions this alert should offer, given what the lead already is.
  function chooseActions(kind, state) {
    if (isTerminal(state)) { return []; }
    var set = SET[kind] || [];
    var s = state || {};
    var out = [];
    for (var i = 0; i < set.length; i++) {
      var a = set[i];
      var cur = CURRENT_STATE_OF[a];
      if (cur && norm(s[cur.field]) === cur.value) { continue; }
      out.push(a);
    }
    return out;
  }

  // ── D3 — never more than two buttons in a row ────────────────────────────────────────────────
  //
  // Straight two-packing in the owner's order reproduces every approved layout exactly:
  //   NEW LEAD  discovery, docs, snooze, nurture      -> [2][2]
  //   PRIORITY  done, snooze, discovery, docs, nurture -> [2][2][1]
  // and it degrades correctly when one action is hidden, which the approved layouts do not
  // themselves specify: five minus one is [2][2], four minus one is [2][1]. Both stay within the
  // rule that matters — two per row — which is what stops Telegram truncating labels to «D…».
  function keyboard(kind, state, leadId) {
    var actions = chooseActions(kind, state);
    var rows = [];
    for (var i = 0; i < actions.length; i += 2) {
      var row = [];
      for (var j = i; j < i + 2 && j < actions.length; j++) {
        row.push({ action: actions[j], text: LABEL[actions[j]], callback_data: callbackData(actions[j], leadId) });
      }
      rows.push(row);
    }
    return rows;
  }

  // The renderer picks a node by SHAPE, because an n8n Telegram node has a fixed number of rows
  // and a fixed number of buttons in each. `NONE` means send the alert with no keyboard at all.
  function shape(rows) {
    if (!rows || rows.length === 0) { return 'NONE'; }
    return 'KB' + rows.map(function (r) { return r.length; }).join('');
  }

  // ── D10 — SPARSE, ACTION-OWNED UPDATES ───────────────────────────────────────────────────────
  //
  // The deployed builder carried FIFTEEN pre-read columns into an autoMap update, so two taps
  // seconds apart wrote each other's stale values back over anything that had changed in between.
  // Each action now writes only the columns it owns. `lead_id` is present because it is the match
  // key, not because it is written.
  //
  // This removes the lost update of UNRELATED columns. It does NOT make two taps that both target
  // `deal_stage` atomic — see RESIDUAL_RACE below.
  var OWNED = {
    done: ['sla_status', 'last_contacted_at'],
    // NARROWED by owner requirement 5: snooze owns the two date fields and NOTHING else.
    // sla_status is deliberately absent — SLA Select already skips a lead whose
    // sla_snooze_until is in the future, so writing 'Snoozed' was cosmetic, and writing a
    // status the action does not need is exactly the drift this pass removes.
    snooze: ['sla_snooze_until', 'next_follow_up_at'],
    discovery: ['deal_stage'],
    docs: ['deal_stage', 'documents_requested_at', 'next_follow_up_at'],
    nurture: ['deal_stage', 'sla_status']
  };

  // The callback verb the handler receives -> the action this module reasons about. `stage` is the
  // deployed verb for Discovery and carries its target stage as an argument.
  function actionOfCommand(command, stageValue) {
    var c = norm(command);
    if (c === 'done') { return 'done'; }
    if (c === 'snooze') { return 'snooze'; }
    if (c === 'docs') { return 'docs'; }
    if (c === 'nurture') { return 'nurture'; }
    if (c === 'stage' && norm(stageValue) === 'discovery scheduled') { return 'discovery'; }
    return '';
  }

  var HOUR = 3600000;

  // Builds the update. `nowIso` is passed in rather than read from the clock so the gate can prove
  // the arithmetic instead of tolerating it.
  function buildUpdate(action, leadId, nowIso) {
    var now = new Date(nowIso);
    var iso = now.toISOString();
    var upd = { lead_id: String(leadId == null ? '' : leadId) };
    if (action === 'done') {
      upd.sla_status = 'Done';
      upd.last_contacted_at = iso;
    } else if (action === 'snooze') {
      // D4 — the measured business action, unchanged: tap time + 24 hours. Storage stays UTC.
      var until = new Date(now.getTime() + 24 * HOUR).toISOString();
      upd.sla_snooze_until = until;
      upd.next_follow_up_at = until;
    } else if (action === 'discovery') {
      // D5 — stage only. No calendar event, no follow-up, no due date, and the confirmation must
      // not pretend otherwise.
      upd.deal_stage = 'Discovery Scheduled';
    } else if (action === 'docs') {
      upd.deal_stage = 'Documents Requested';
      upd.documents_requested_at = iso;
      upd.next_follow_up_at = new Date(now.getTime() + 48 * HOUR).toISOString();
    } else if (action === 'nurture') {
      upd.deal_stage = 'Nurture';
      upd.sla_status = 'Nurture';
    } else {
      return null;
    }
    return upd;
  }

  // ── D11 — is this tap a no-op? ───────────────────────────────────────────────────────────────
  //
  // Read from the freshly-read row, never from the alert the tap came from. An already-applied
  // action is acknowledged harmlessly and performs NO write, which is what stops a duplicate tap
  // moving `documents_requested_at` or re-basing a snooze the owner did not ask to move.
  function alreadyApplied(action, row) {
    var r = row || {};
    if (action === 'done') { return norm(r.sla_status) === 'done'; }
    if (action === 'discovery') { return norm(r.deal_stage) === 'discovery scheduled'; }
    if (action === 'docs') { return norm(r.deal_stage) === 'documents requested'; }
    if (action === 'nurture') { return norm(r.deal_stage) === 'nurture' && norm(r.sla_status) === 'nurture'; }
    // Snooze is deliberately NOT idempotent-by-state: «отложить ещё на 24 часа» is a real
    // instruction, and refusing it because the lead is already Snoozed would be wrong. It is safe
    // to repeat because it re-bases from the tap time rather than compounding.
    return false;
  }

  // Decided against the FRESHLY READ row, never against the state the alert was rendered with.
  //
  // Three distinct refusals, because the owner is told three different things (D10):
  //   TERMINAL         the lead is closed for actions
  //   ALREADY_APPLIED  this exact action is already the current state
  //   STATE_CHANGED    the lead moved on, and this action is no longer one of the valid ones
  function refuseReason(action, row, kind) {
    if (!action) { return 'UNKNOWN_ACTION'; }
    if (isTerminal(row)) { return 'TERMINAL'; }
    if (alreadyApplied(action, row)) { return 'ALREADY_APPLIED'; }
    if (kind && chooseActions(kind, row).indexOf(action) === -1) { return 'STATE_CHANGED'; }
    return '';
  }

  // ── POST-WRITE VERIFICATION ──────────────────────────────────────────────────────────────────
  //
  // The owner is not told an action succeeded because a Sheets node did not throw. The row is read
  // back and every field the action claimed to write is compared to what it intended. A mismatch
  // is a failed action, and it is reported as one.
  function verifyMutation(upd, row) {
    var mismatched = [];
    var r = row || {};
    for (var k in upd) {
      if (!Object.prototype.hasOwnProperty.call(upd, k)) { continue; }
      if (k === 'lead_id') { continue; }
      if (String(r[k] == null ? '' : r[k]) !== String(upd[k] == null ? '' : upd[k])) {
        mismatched.push(k);
      }
    }
    return { ok: mismatched.length === 0, mismatched: mismatched };
  }

  // Which fields an action must leave alone — everything on the row it does not own. Used by the
  // gate to prove preservation against a real pre-image rather than against a short allow-list.
  function untouchedFields(action, row) {
    var owned = (OWNED[action] || []).concat(['lead_id']);
    var out = [];
    for (var k in (row || {})) {
      if (Object.prototype.hasOwnProperty.call(row, k) && owned.indexOf(k) === -1) { out.push(k); }
    }
    return out;
  }

  // ── the owner-facing confirmation ────────────────────────────────────────────────────────────
  //
  // Rendered only AFTER the authoritative Pipeline write succeeds (D8/D9). Every date is shown in
  // Europe/Chisinau via the presenter's own formatter; storage stays UTC (D4).
  var TITLE = {
    done: 'ACTION UPDATED',
    snooze: 'FOLLOW-UP UPDATED',
    discovery: 'STAGE UPDATED',
    docs: 'ACTION UPDATED',
    nurture: 'STAGE UPDATED'
